export const experienceEntries = roles.map((entry) => {
  const detailGroups = entry.detailGroups ?? [{ details: entry.details }];
  const details = detailGroups.flatMap((group) => group.details);
  return {
    ...entry,
    detailGroups,
    details,
    descriptions: [entry.summary, ...details.map((detail) => detail.body)],
  };
});
export function experienceById(id) {
  return experienceEntries.find((entry) => entry.id === id);
}
